Part I — C (1.5 marks). Which statements correctly identify problems in this function?
```c
#include <stdlib.h>
#include <string.h>

char *copy_label(const char *src) {
    char *buf = malloc(strlen(src));
    strcpy(buf, src);
    return buf;
}
```

Part I — C (2 marks). Consider this code. Which statements are correct?
```c
#include <stdio.h>

void touch(int a[4]) {
    printf("%zu\n", sizeof(a));
    a[4] = 99;
}

int main(void) {
    int xs[4] = {1, 2, 3, 4};
    touch(xs);
}
```

Part I — C (1.5 marks). Which statements are correct about this signed/unsigned comparison?
```c
#include <stdio.h>

int main(void) {
    int i = -1;
    unsigned int u = 1;

    if (i < u)
        puts("less");
    else
        puts("not less");
}
```

Part II — Compilation (2 marks). Given this source-level fragment, which statements about compiler stages are correct?
```c
int x;
x = true + 3;
```

Part III — C++ (2 marks). This code intentionally avoids standard-library classes. Which statements are correct?
```cpp
class Base {
public:
    ~Base() {}
    virtual int value() const { return 1; }
};

class Derived : public Base {
    int *data;
public:
    Derived() : data(new int[8]) {}
    ~Derived() { delete[] data; }
    int value() const override { return 2; }
};

int main() {
    Base *p = new Derived();
    int n = p->value();
    delete p;
}
```

Part III — C++ (3 marks). Match each fragment to the concept it mainly tests. No standard-library classes are needed.
```cpp
class A { int x; public: virtual int f(){ return 1; } };
class B : public A { public: int f() override { return 2; } };
int g(int);
double g(double);
```

